import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const UPDATE = 'MVP Trainer Music R67';
const repoRoot = process.cwd();
const packageJson = path.join(repoRoot, 'package.json');

if (!fs.existsSync(packageJson)) {
  console.error('ERROR: Run this command from the root of the MVP Trainer repository (the folder containing package.json).');
  process.exit(1);
}

const payload = {"src/features/music/MusicPage.tsx":{"b64":"","sha256":"1474008e961cdb27f7c328c1ba3b2cac75455b917d09f53173037c359cd2bdbb","bytes":205224},"src/lib/musicMetadata.ts":{"b64":"","sha256":"232272a7c8d0484e7d52842b45f625b281605d25bf76b96de7eb1a9c2a3a0707","bytes":41703}};

function sha256(buf) { return crypto.createHash('sha256').update(buf).digest('hex'); }

console.log(`\n${UPDATE}`);
console.log('Applying 2 project-file updates...\n');

for (const [rel, meta] of Object.entries(payload)) {
  const target = path.join(repoRoot, ...rel.split('/'));
  const data = Buffer.from(meta.b64, 'base64');
  if (data.length !== meta.bytes || sha256(data) !== meta.sha256) {
    console.error(`ERROR: Embedded payload validation failed for ${rel}`);
    process.exit(1);
  }
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, data);
  const written = fs.readFileSync(target);
  if (sha256(written) !== meta.sha256) {
    console.error(`ERROR: File verification failed after writing ${rel}`);
    process.exit(1);
  }
  console.log(`UPDATED  ${rel}`);
}

console.log('\nR67 installed successfully.');
console.log('Next: run npm run build, review the 2 changed project files in GitHub Desktop, then commit/push.\n');
